/*
PostgreSQL DBA Script: Like Ilike Query Candidates
Purpose: Find LIKE/ILIKE-heavy statements that may need trigram/full-text strategy.
Area: Complex Filtering and Search
Usage: Requires pg_stat_statements.
Sample Output: See SAMPLE_OUTPUT_BEGIN block at the bottom for a representative result shape.
Notes: Read-only diagnostic unless the script explicitly creates objects, changes settings, or seeds/fixes lab data.
*/

SELECT
    stats_reset AS pgss_stats_reset,
    clock_timestamp() - stats_reset AS statistics_age,
    'All following counters are cumulative since pgss_stats_reset; use snapshots for an incident interval.' AS measurement_boundary
FROM pg_stat_statements_info;

SELECT
    queryid,
    calls,
    total_exec_time,
    mean_exec_time,
    shared_blks_read,
    temp_blks_written,
    regexp_replace(query, '\s+', ' ', 'g') AS query_snippet
FROM pg_stat_statements
WHERE query ILIKE '% like %'
   OR query ILIKE '% ilike %'
ORDER BY total_exec_time DESC
LIMIT 200;




